def count_permutation_polynomials_ax3_bx(p):
    count = 0
    for a in range(p):
        for b in range(p):
            # Check if ax^3 + bx is a permutation polynomial modulo p
            seen = set()
            is_perm = True
            for x in range(p):
                y = (a * (x**3) + b * x) % p
                if y in seen:
                    is_perm = False
                    break
                seen.add(y)
            if is_perm:
                count += 1
    return count

